import sys


def main():
    jobs = []
    for line in sys.stdin:
        parts = line.strip().split()
        if parts:
            name, arrival, duration, priority = parts
            jobs.append((name, int(arrival), int(duration), int(priority)))
    jobs.sort(key=lambda j: (-j[3], j[1], j[0]))
    time = 0
    idle = 0
    schedule = []
    while jobs:
        best_job = None
        for job in jobs:
            if job[1] <= time and job not in schedule:
                if best_job is None or (job[3] > best_job[3]) or (
                    job[3] == best_job[3] and job[1] < best_job[1]
                ) or (
                    job[3] == best_job[3] and job[1] == best_job[1] and job[0] < best_job[0]
                ):
                    best_job = job
        if best_job is not None:
            schedule.append(best_job)
            time = max(time, best_job[1])
            end_time = time + best_job[2]
            schedule.append((best_job[0], end_time))
            time = end_time
        else:
            idle += time
            time += 1
    for name, start, end in schedule:
        print(f"{name} {start} {end}")
    print(f"idle {idle}")


if __name__ == "__main__":
    main()
